 void updateTargets(){if(target==null)return;int t=sourceType.getSelectedItemPosition();String[] a=t==0?new String[]{"-"}:t==1?new String[]{"Main LR"}:t==2?busList():t==3?matrixList():inputList();target.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,a));target.setSelection(0);}String[] busList(){String[] a=new String[16];for(int i=1;i<=16;i++)a[i-1]=String.format("Bus %02d",i);return a;}String[] matrixList(){String[] a=new String[6];for(int i=1;i<=6;i++)a[i-1]=String.format("Matrix %02d",i);return a;}String[] inputList(){String[] a=new String[32];for(int i=1;i<=32;i++)a[i-1]=String.format("Input %02d",i);return a;}void showNoSource(){syncing=true;sourceType.setSelection(0);target.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"-"}));target.setSelection(0);syncing=false;}
 String routeBase(){if("-".equals(targetName()))return "";int t=sourceType.getSelectedItemPosition();if(t==1)return "/main/st/insert";int n=Integer.parseInt(targetName().replaceAll("\\D",""));if(t==2)return String.format("/bus/%02d/insert",n);if(t==3)return String.format("/mtx/%02d/insert",n);if(t==4)return String.format("/ch/%02d/insert",n);return "";}String targetName(){return String.valueOf(target.getSelectedItem());}int fx(){return 5+fxSlot.getSelectedItemPosition();}int par(int b){return 1+b+(side.getSelectedItemPosition()==0?0:32);}String pa(int p){return String.format("/fx/%d/par/%02d",fx(),p);}int rtaSource(){if("-".equals(targetName()))return -1;int t=sourceType.getSelectedItemPosition();if(t==1)return 72;int n=Integer.parseInt(targetName().replaceAll("\\D",""));if(t==2)return 49+n;if(t==3)return 65+n;if(t==4)return 1+n;return -1;}int delay(){int[] a={1,25,50,100,150,250,500,1000};return a[delayMs.getSelectedItemPosition()];}float cut(){return 1+cutDb.getSelectedItemPosition();}boolean geqOk(){return fxType==0||fxType==2;}String fxName(){return fxType>=0&&fxType<FXN.length?FXN[fxType]:"-";}
 void connect(){mixerIp=ip.getText().toString().trim();disconnect();new Thread(()->{try{socket=new DatagramSocket();socket.setSoTimeout(700);running=true;sendNow("/info");DatagramPacket p=new DatagramPacket(new byte[2048],2048);socket.receive(p);connected=true;runOnUiThread(()->{status.setText("M32R CONNECTED");status.setTextColor(Color.rgb(52,211,153));startStop.setEnabled(true);});new Thread(this::rx).start();new Thread(this::keep).start();scanRoutes();syncFromSource();}catch(Exception e){runOnUiThread(()->status.setText("NO RESPONSE"));disconnect();}}).start();}
