 void syncFromSource(){if(!connected||"-".equals(targetName()))return;stopEngine();String b=routeBase();if(b.length()==0)return;send(b+"/sel");send(b+"/on");int rs=rtaSource();if(rs>=0)send("/-prefs/rta/source",rs);new Handler(getMainLooper()).postDelayed(()->{Integer s=routeSel.get(b),on=routeOn.get(b);if(s!=null&&s>=8&&s<=15&&on!=null&&on!=0){int rack=s/2+1;if(rack>=5&&rack<=8){syncing=true;fxSlot.setSelection(rack-5);syncing=false;readGeq();updateRouteText();return;}}routeState.setText("SOURCE: "+targetName()+"   |   INSERT: OFF/-   |   FX TYPE: -   |   SIDE: "+side.getSelectedItem());},300);}
