 void decode(byte[] b){int off=b.length>=204?4:0;if(b.length-off<200)return;ByteBuffer q=ByteBuffer.wrap(b,off,200).order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<100;i++)rta[i]=q.getShort()/256f;runOnUiThread(()->{analyzer.setRta(rta);rtaState.setText("RTA LIVE • "+targetName()+" ↔ FX"+fx()+"-"+side.getSelectedItem());});if(engineRunning){if(operation.getSelectedItemPosition()==0)feedback();else flat();}}
 void feedback(){int bi=-1;float best=0;for(int i=18;i<94;i++){if(rta[i]<-48||rta[i]<=rta[i-1]||rta[i]<=rta[i+1])continue;float s=0;int n=0;for(int j=i-4;j<=i+4;j++)if(j>=0&&j<100&&Math.abs(j-i)>=2){s+=rta[j];n++;}float ex=rta[i]-s/n;if(ex>6.5&&ex>best){best=ex;bi=i;}}if(bi<0){candStart=0;candBand=-1;return;}int band=nearBand(RF[bi]);if(band!=candBand){candBand=band;candStart=System.currentTimeMillis();return;}long held=System.currentTimeMillis()-candStart;runOnUiThread(()->candidate.setText("Feedback: "+(int)GF[candBand]+" Hz • "+held+" / "+delay()+" ms"));if(held>=delay()){int p=par(band);float old=cur.containsKey(p)?den(cur.get(p)):0;push();write(band,Math.max(-15,old-cut()));candStart=0;candBand=-1;}}
