 int nearBand(float f){int b=0;double d=99;for(int i=0;i<31;i++){double x=Math.abs(Math.log(GF[i]/f));if(x<d){d=x;b=i;}}return b;}int nearRta(float f){int b=0;double d=99;for(int i=0;i<100;i++){double x=Math.abs(Math.log(RF[i]/f));if(x<d){d=x;b=i;}}return b;}void push(){undo.push(new HashMap<>(cur));if(undo.size()>12)undo.removeLast();}void write(int b,float db){float v=norm(db);cur.put(par(b),v);geq[b]=db;send(pa(par(b)),v);runOnUiThread(()->analyzer.setGeq(geq));}float norm(float d){return Math.max(0,Math.min(1,(d+15)/30));}float den(float v){return v*30-15;}void undo(){if(undo.isEmpty())return;HashMap<Integer,Float> m=undo.pop();for(Map.Entry<Integer,Float> e:m.entrySet())send(pa(e.getKey()),e.getValue());cur.clear();cur.putAll(m);readGeq();}void restore(){for(Map.Entry<Integer,Float> e:snap.entrySet())send(pa(e.getKey()),e.getValue());readGeq();}
 byte[] osc(String a,Object...x)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream(),p=new ByteArrayOutputStream();StringBuilder t=new StringBuilder(",");for(Object z:x){if(z instanceof Integer){t.append('i');p.write(ByteBuffer.allocate(4).order(ByteOrder.BIG_ENDIAN).putInt((Integer)z).array());}else if(z instanceof Float){t.append('f');p.write(ByteBuffer.allocate(4).order(ByteOrder.BIG_ENDIAN).putFloat((Float)z).array());}}o.write(pad(a));o.write(pad(t.toString()));o.write(p.toByteArray());return o.toByteArray();}byte[] pad(String s)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();o.write(s.getBytes(StandardCharsets.UTF_8));o.write(0);while(o.size()%4!=0)o.write(0);return o.toByteArray();}String rs(byte[] d,int[] o){int i=o[0],e=i;while(e<d.length&&d[e]!=0)e++;String s=new String(d,i,e-i,StandardCharsets.UTF_8);o[0]=(e+4)&~3;return s;}
