 public static class EqView extends View{Paint p=new Paint(1);float[] rta=new float[100],g=new float[31];int mode;String header="M32R DUAL GRAPHIC EQ";EqView(android.content.Context c){super(c);Arrays.fill(rta,-90);}void setRta(float[] a){rta=a.clone();invalidate();}void setGeq(float[] a){g=a.clone();invalidate();}void setHeader(String s){header=s;invalidate();}protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight();if(mode==0){drawRack(c,w,h);return;}float top=25,bot=h-35,mid=(top+bot)/2;p.setStrokeWidth(1);p.setColor(Color.rgb(35,48,63));for(int i=0;i<=6;i++){float y=top+(bot-top)*i/6;c.drawLine(0,y,w,y,p);}boolean rr=mode==3||mode==4||mode==5,bar=mode==1||mode==5,curve=mode==2||mode==4;if(rr){p.setColor(Color.rgb(56,189,248));p.setStrokeWidth(2);Path q=new Path();for(int i=0;i<100;i++){float x=w*i/99f,y=top+(-Math.max(-90,Math.min(0,rta[i]))/90)*(bot-top);if(i==0)q.moveTo(x,y);else q.lineTo(x,y);}c.drawPath(q,p);}if(bar){float bw=w/31;p.setStrokeWidth(Math.max(3,bw*.55f));for(int i=0;i<31;i++){float x=bw*(i+.5f),y=mid-Math.max(-15,Math.min(15,g[i]))/15*(bot-top)/2;p.setColor(g[i]<-.1?Color.RED:g[i]>.1?Color.GREEN:Color.GRAY);c.drawLine(x,mid,x,y,p);}}if(curve){p.setColor(Color.rgb(52,211,153));p.setStrokeWidth(3);Path q=new Path();for(int i=0;i<31;i++){float x=w*i/30f,y=mid-Math.max(-15,Math.min(15,g[i]))/15*(bot-top)/2;if(i==0)q.moveTo(x,y);else q.lineTo(x,y);}c.drawPath(q,p);for(int i=0;i<31;i++){float x=w*i/30f,y=mid-Math.max(-15,Math.min(15,g[i]))/15*(bot-top)/2;c.drawCircle(x,y,4,p);}}labels(c,w,h);}void drawRack(Canvas c,float w,float h){p.setColor(Color.rgb(16,43,69));c.drawRect(0,0,w,h,p);p.setColor(Color.rgb(22,58,91));c.drawRect(0,0,w,56,p);p.setColor(Color.WHITE);p.setTextSize(21);p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText("DUAL GRAPHIC EQ",14,35,p);p.setTextSize(14);p.setColor(Color.rgb(238,199,76));c.drawText(header,190,34,p);float top=92,bot=h-72,zero=top+(bot-top)*.5f;p.setTypeface(Typeface.DEFAULT);p.setStrokeWidth(1);for(int i=0;i<=6;i++){float y=top+(bot-top)*i/6f;p.setColor(i==3?Color.rgb(148,174,197):Color.rgb(65,94,121));c.drawLine(40,y,w-8,y,p);}p.setTextSize(12);p.setColor(Color.WHITE);c.drawText("+15",5,top+4,p);c.drawText("+10",5,top+(bot-top)/6+4,p);c.drawText("+5",12,top+(bot-top)*2/6+4,p);c.drawText("0",18,zero+4,p);c.drawText("-5",12,top+(bot-top)*4/6+4,p);c.drawText("-10",5,top+(bot-top)*5/6+4,p);c.drawText("-15",5,bot+4,p);float left=44,right=w-10,bw=(right-left)/31f;for(int i=0;i<31;i++){float x=left+bw*(i+.5f),db=Math.max(-15,Math.min(15,g[i])),y=zero-db/30f*(bot-top);p.setStrokeWidth(Math.max(3,bw*.30f));p.setColor(Color.rgb(18,31,42));c.drawLine(x,top,x,bot,p);p.setColor(Color.rgb(188,208,225));float hw=Math.max(5,bw*.36f),hh=8;c.drawRect(x-hw,y-hh,x+hw,y+hh,p);p.setColor(Color.rgb(70,103,132));c.drawRect(x-hw+2,y-1,x+hw-2,y+2,p);}String[] labs={"20","25","31","40","50","63","80","100","125","160","200","250","315","400","500","630","800","1k","1.25k","1.6k","2k","2.5k","3.15k","4k","5k","6.3k","8k","10k","12.5k","16k","20k"};p.setTextSize(9);p.setColor(Color.WHITE);for(int i=0;i<31;i++){float x=left+bw*(i+.5f);c.save();c.rotate(-90,x,h-8);c.drawText(labs[i],x,h-8,p);c.restore();}}void labels(Canvas c,float w,float h){p.setColor(Color.LTGRAY);p.setTextSize(14);c.drawText("20",2,h-8,p);c.drawText("100",w*.22f,h-8,p);c.drawText("1k",w*.52f,h-8,p);c.drawText("10k",w*.82f,h-8,p);c.drawText("20k",w-30,h-8,p);}}
